#' Synoptic Report Completeness
#'
#' Audits the completeness of structured / synoptic pathology reports: the 
#' proportion of required data elements present per report, per required 
#' element, and by subspecialty or reporting pathologist, with an optional 
#' completeness trend over time.
#' 
#' @param data .
#' @param items The required synoptic data elements. Each is counted as
#'   present for a report when it is non-missing (and, for text, not blank or an
#'   explicit absence marker).
#' @param presenceRule How each element is judged present.
#' @param presentValue When the rule is "specified value", the value that
#'   marks an element present.
#' @param group Optional grouping for stratified completeness (e.g.
#'   subspecialty or reporting pathologist).
#' @param timeVar Optional ordered time/period variable for a completeness
#'   trend.
#' @param completeThreshold A report counts as complete when at least this
#'   percentage of elements are present.
#' @param showOverall .
#' @param showPerItem .
#' @param showByGroup .
#' @param showTrend .
#' @param showPlot .
#' @param showSummary .
#' @param showExplanation .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$overallTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$perItemTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$byGroupTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$trendTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$addCompletenessToData} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$overallTable$asDF}
#'
#' \code{as.data.frame(results$overallTable)}
#'
#' @export
synopticcompleteness <- function(
    data,
    items,
    presenceRule = "nonmissing",
    presentValue = "",
    group,
    timeVar,
    completeThreshold = 100,
    showOverall = TRUE,
    showPerItem = TRUE,
    showByGroup = TRUE,
    showTrend = TRUE,
    showPlot = TRUE,
    showSummary = TRUE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("synopticcompleteness requires jmvcore to be installed (restart may be required)")

    if ( ! missing(items)) items <- jmvcore::resolveQuo(jmvcore::enquo(items))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(timeVar)) timeVar <- jmvcore::resolveQuo(jmvcore::enquo(timeVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(items), items, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(timeVar), timeVar, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- synopticcompletenessOptions$new(
        items = items,
        presenceRule = presenceRule,
        presentValue = presentValue,
        group = group,
        timeVar = timeVar,
        completeThreshold = completeThreshold,
        showOverall = showOverall,
        showPerItem = showPerItem,
        showByGroup = showByGroup,
        showTrend = showTrend,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- synopticcompletenessClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

